guU(){return"\u0627\u0633\u0645 \u0645\u0633\u062a\u062e\u062f\u0645 Last.fm"},
guP(){return"\u0646\u0641\u0633 \u0645\u0641\u062a\u0627\u062d API \u0627\u0644\u062e\u0627\u0635 \u0628\u0627\u0644\u062d\u0633\u0627\u0628 \u0627\u0644\u0646\u0634\u0637"},
gmT(){return"\u0645\u0641\u062a\u0627\u062d API"},
guy(){return"\u0625\u0636\u0627\u0641\u0629"},
gA6(){return"\u062a\u062a\u063a\u064a\u0631 \u0627\u0644\u0644\u063a\u0629 \u0641\u0648\u0631\u064b\u0627 \u0641\u064a \u0643\u0627\u0645\u0644 \u0627\u0644\u062a\u0637\u0628\u064a\u0642."},
gpX(){return"\u0625\u062c\u0645\u0627\u0644\u064a \u0627\u0644\u062a\u0634\u063a\u064a\u0644\u0627\u062a"},
gpR(){return"\u0639\u0636\u0648 \u0645\u0646\u0630"},
gpN(){return"\u0627\u0644\u062f\u0648\u0644\u0629"},
gpK(){return"\u0627\u0644\u0641\u0646\u0627\u0646 \u0631\u0642\u0645 1 (\u0627\u0644\u0623\u0633\u0628\u0648\u0639)"},
gpI(){return"\u0627\u0644\u0623\u0644\u0628\u0648\u0645 \u0631\u0642\u0645 1 (\u0627\u0644\u0623\u0633\u0628\u0648\u0639)"},
gpZ(){return"\u0627\u0644\u0645\u0642\u0637\u0639 \u0631\u0642\u0645 1 (\u0627\u0644\u0623\u0633\u0628\u0648\u0639)"},
gq0(){return"\u0641\u0646\u0627\u0646\u0648\u0646 \u0641\u0631\u064a\u062f\u0648\u0646"},
gq1(){return"\u0645\u0642\u0627\u0637\u0639 \u0641\u0631\u064a\u062f\u0629"},
gq_(){return"\u0623\u0644\u0628\u0648\u0645\u0627\u062a \u0641\u0631\u064a\u062f\u0629"},
gxN(){return"\u0647\u0630\u0627 \u0627\u0644\u0623\u0633\u0628\u0648\u0639"},
gxp(){return"\u064a"},
gtp(){return"\u062a\u0641\u0639\u064a\u0644 \u0627\u0644\u0645\u0641\u0636\u0644\u0629 (\u0627\u062e\u062a\u064a\u0627\u0631\u064a)"},
gtq(){return"\u0627\u0644\u0645\u0641\u062a\u0627\u062d \u0627\u0644\u0633\u0631\u064a \u064a\u062a\u064a\u062d \u0644\u0644\u062a\u0637\u0628\u064a\u0642 \u0625\u0636\u0627\u0641\u0629 \u0623\u0648 \u0625\u0632\u0627\u0644\u0629 \u0627\u0644\u0645\u0642\u0637\u0648\u0639\u0627\u062a \u0645\u0646 \u0627\u0644\u0645\u0641\u0636\u0644\u0629 \u0645\u0628\u0627\u0634\u0631\u0629 \u0639\u0644\u0649 Last.fm."},
gtv(){return"\u0627\u0644\u0645\u0641\u062a\u0627\u062d \u0627\u0644\u0633\u0631\u064a \u0644\u0640 Last.fm"},
gzc(){return"\u064a\u062c\u0628 \u0623\u0646 \u064a\u062a\u0643\u0648\u0646 \u0627\u0644\u0645\u0641\u062a\u0627\u062d \u0627\u0644\u0633\u0631\u064a \u0645\u0646 32 \u062d\u0631\u0641\u064b\u0627."},
